class GomokuGame:
    EMPTY_CELL = ' '
    PLAYER_X = 'X'
    PLAYER_O = 'O'
    WIN_THRESHOLD = 5

    def __init__(self, board_size):
        self.board_size = board_size
        self._board = [[self.EMPTY_CELL for _ in range(board_size)] for _ in range(board_size)]
        self._current_player = self.PLAYER_X

    @property
    def board(self):
        return self._board

    @property
    def current_player(self):
        return self._current_player

    def make_move(self, row, col):
        if not self._is_valid_move(row, col):
            return False
        self._place_piece(row, col)
        self._switch_player()
        return True

    def _is_valid_move(self, row, col):
        return self._board[row][col] == self.EMPTY_CELL

    def _place_piece(self, row, col):
        self._board[row][col] = self._current_player

    def _switch_player(self):
        self._current_player = self.PLAYER_O if self._current_player == self.PLAYER_X else self.PLAYER_X

    def check_winner(self):
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for row in range(self.board_size):
            for col in range(self.board_size):
                if not self._is_occupied(row, col):
                    continue
                for direction in directions:
                    if self._check_five_in_a_row(row, col, direction):
                        return self._get_cell_symbol(row, col)
        return None

    def _is_occupied(self, row, col):
        return self._board[row][col] != self.EMPTY_CELL

    def _get_cell_symbol(self, row, col):
        return self._board[row][col]

    def _check_five_in_a_row(self, row, col, direction):
        dx, dy = direction
        symbol = self._get_cell_symbol(row, col)
        if not self._has_five_in_direction(row, col, dx, dy, symbol):
            return False
        return True

    def _has_five_in_direction(self, row, col, dx, dy, symbol):
        for i in range(1, self.WIN_THRESHOLD):
            new_row = row + dx * i
            new_col = col + dy * i
            if not self._is_in_bounds(new_row, new_col):
                return False
            if self._get_cell_symbol(new_row, new_col) != symbol:
                return False
        return True

    def _is_in_bounds(self, row, col):
        return 0 <= row < self.board_size and 0 <= col < self.board_size
